public abstract class QuerydslSupport {

    private final JPAQueryFactory queryFactory;

    protected QuerydslSupport(JPAQueryFactory queryFactory) {
        this.queryFactory = queryFactory;
    }

    protected JPAQueryFactory query() {
        return queryFactory;
    }

    /** 정렬 허용 목록. 엔티티마다 다르다. */
    protected abstract Map<String, ComparableExpressionBase<?>> sortable();

    protected abstract OrderSpecifier<?> defaultOrder();

    protected OrderSpecifier<?>[] toOrders(Sort sort) {
        if (sort.isUnsorted()) {
            return new OrderSpecifier[]{ defaultOrder() };
        }
        Map<String, ComparableExpressionBase<?>> allowed = sortable();
        List<OrderSpecifier<?>> orders = sort.stream()
                .map(o -> {
                    var path = allowed.get(o.getProperty());
                    if (path == null) return defaultOrder();
                    return o.isAscending() ? path.asc() : path.desc();
                })
                .toList();
        return orders.toArray(OrderSpecifier[]::new);
    }

    protected <T> JPAQuery<T> applyPagination(JPAQuery<T> query,
                                              Pageable pageable) {
        return query
                .orderBy(toOrders(pageable.getSort()))
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize());
    }

    protected <T> Page<T> applyPage(JPAQuery<T> contentQuery,
                                    JPAQuery<Long> countQuery,
                                    Pageable pageable) {
        List<T> content = applyPagination(contentQuery, pageable).fetch();
        return PageableExecutionUtils.getPage(content, pageable,
                countQuery::fetchOne);
    }
}

