public class MemberRepositoryCustomImpl extends QuerydslSupport
        implements MemberRepositoryCustom {

    public MemberRepositoryCustomImpl(JPAQueryFactory queryFactory) {
        super(queryFactory);
    }

    @Override
    protected Map<String, ComparableExpressionBase<?>> sortable() {
        return Map.of(
                "age", member.age,
                "username", member.username,
                "teamName", team.name);
    }

    @Override
    protected OrderSpecifier<?> defaultOrder() {
        return member.id.asc();
    }

    @Override
    public Page<MemberTeamDto> searchPage(MemberSearchCondition cond,
                                          Pageable pageable) {
        BooleanExpression predicate = Expressions.allOf(
                usernameEq(cond.getUsername()),
                teamNameEq(cond.getTeamName()),
                ageBetween(cond.getAgeGoe(), cond.getAgeLoe()));

        JPAQuery<MemberTeamDto> content = query()
                .select(new QMemberTeamDto(
                        member.id, member.username, member.age,
                        team.id, team.name))
                .from(member)
                .leftJoin(member.team, team)
                .where(predicate);

        JPAQuery<Long> count = query()
                .select(member.count())
                .from(member)
                .leftJoin(member.team, team)
                .where(predicate);

        return applyPage(content, count, pageable);
    }
}

