public class TeamRepositoryCustomImpl extends QuerydslSupport
        implements TeamRepositoryCustom {

    public TeamRepositoryCustomImpl(JPAQueryFactory queryFactory) {
        super(queryFactory);
    }

    @Override
    protected Map<String, ComparableExpressionBase<?>> sortable() {
        return Map.of("name", team.name);
    }

    @Override
    protected OrderSpecifier<?> defaultOrder() {
        return team.id.asc();
    }

    @Override
    public Page<TeamStat> statsPage(Pageable pageable) {
        JPAQuery<TeamStat> content = query()
                .select(new QTeamStat(team.name, member.count(),
                        member.age.avg()))
                .from(member)
                .join(member.team, team)
                .groupBy(team.name);

        JPAQuery<Long> count = query()
                .select(team.countDistinct())
                .from(member)
                .join(member.team, team);

        return applyPage(content, count, pageable);
    }
}

