-- 지원 클래스만 테스트한다

class QuerydslSupportTest {

    static class TestSupport extends QuerydslSupport {
        TestSupport() { super(null); }
        @Override protected Map<String, ComparableExpressionBase<?>> sortable() {
            return Map.of("age", member.age);
        }
        @Override protected OrderSpecifier<?> defaultOrder() {
            return member.id.asc();
        }
        OrderSpecifier<?>[] orders(Sort sort) { return toOrders(sort); }
    }

    @Test
    void 허용된_속성() {
        assertThat(new TestSupport().orders(Sort.by("age"))[0])
                .hasToString("member1.age ASC");
    }

    @Test
    void 허용_안_된_속성() {
        assertThat(new TestSupport().orders(Sort.by("없는것"))[0])
                .hasToString("member1.id ASC");
    }

    @Test
    void 정렬이_없으면() {
        assertThat(new TestSupport().orders(Sort.unsorted())[0])
                .hasToString("member1.id ASC");
    }
}

